test('V98 production vulnerability evidence modes are required',()=>{
  const base={NODE_ENV:'development'};
  assert.doesNotThrow(()=>validateEnv(base));
  const source=validateEnv.toString();
  assert.match(source,/VULNERABILITY_EVIDENCE_MODE/);
  assert.match(source,/VULNERABILITY_RELEASE_GATE_MODE/);
  assert.match(source,/VEX_OVERRIDE_MODE/);
});


